    correctAnswer:"Wearing broad-spectrum sunscreen of SPF 30 or higher and limiting time in strong sun",
    explanation:"Ultraviolet (UV) light damages skin cells, and the damage adds up over time. Sunscreen, shade, and protective clothing lower exposure all year. Tanning, including tanning beds, raises risk instead of protecting skin.",
